;(async function () {
  'use strict';
  const REPO = 'Mio-Ame/user-persona-picker';
  const BRANCH = 'main';
  const FILE = 'user-persona-picker.js';
  const CACHE_KEY = 'userPersonaPicker.remoteCache.v5';

  const ts = Date.now();
  const urls = [
    `https://raw.githubusercontent.com/${REPO}/${BRANCH}/${FILE}?t=${ts}`,
    `https://testingcf.jsdelivr.net/gh/${REPO}@${BRANCH}/${FILE}?t=${ts}`,
    `https://fastly.jsdelivr.net/gh/${REPO}@${BRANCH}/${FILE}?t=${ts}`,
  ];

  async function fetchCode() {
    for (const url of urls) {
      try {
        const res = await fetch(url, { cache: 'no-store' });
        if (!res.ok) continue;
        const code = await res.text();
        if (code && code.includes('user-persona-picker-host')) {
          try { localStorage.setItem(CACHE_KEY, code); } catch (_) {}
          return code;
        }
      } catch (_) {}
    }
    try {
      const cached = localStorage.getItem(CACHE_KEY);
      if (cached) return cached;
    } catch (_) {}
    throw new Error('拉取远程脚本失败，请检查网络');
  }

  try {
    const code = await fetchCode();
    const blobUrl = URL.createObjectURL(new Blob([code], { type: 'text/javascript' }));
    try {
      await import(blobUrl);
    } finally {
      URL.revokeObjectURL(blobUrl);
    }
  } catch (err) {
    const t = window.parent?.toastr || window.toastr;
    if (t?.error) t.error('[User人设] ' + (err?.message || err));
    console.error('[User人设]', err);
  }
})();
